data=json.loads("\"diff --git a/skills/codex-delegate/scripts/relay.mjs b/skills/codex-delegate/scripts/relay.mjs\\nindex 70372f8..71d9f1e 100644\\n--- a/skills/codex-delegate/scripts/relay.mjs\\n+++ b/skills/codex-delegate/scripts/relay.mjs\\n@@ -164,12 +164,7 @@ function timestamp() {\\n function buildArgv(opts, finalPath) {\\n   const argv = [\\\"exec\\\"];\\n   if (opts.resumeLast) argv.push(\\\"resume\\\", \\\"--last\\\");\\n-  // ponytail: shell:true on win32 (needed for the codex.cmd shim) doesn't quote\\n-  // args, so a temp path with spaces (C:\\\\Users\\\\First Last\\\\...) splits and the\\n-  // trailing \\\"-\\\" misparses (issue #3). Quote the only spaceable arg in argv.\\n-  // Ceiling: if quoting proves too blunt, drop shell:true and resolve the shim.\\n-  const outPath = process.platform === \\\"win32\\\" ? `\\\"${finalPath}\\\"` : finalPath;\\n-  argv.push(\\\"--json\\\", \\\"-o\\\", outPath);\\n+  argv.push(\\\"--json\\\", \\\"-o\\\", finalPath);\\n   // `-s`/`-C` are not accepted by `exec resume`; resume inherits the original\\n   // session's sandbox and working root, and we set the child process cwd below.\\n   if (!opts.resumeLast) {\\n@@ -251,12 +246,43 @@ function reportUnavailable(writeResult, resultPath) {\\n   process.exit(127);\\n }\\n \\n+/**\\n+ * The Windows npm installation exposes codex.cmd rather than an executable.\\n+ * Pass a single, explicitly quoted command to cmd.exe instead of using\\n+ * spawn(..., { shell: true }), which does not preserve argv boundaries there.\\n+ * Reject cmd expansions/quote delimiters rather than treating untrusted model\\n+ * names or filesystem paths as shell syntax.\\n+ */\\n+function quoteForCmd(arg) {\\n+  const value = String(arg);\\n+  if (/[\\\\r\\\\n\\\\x00%\\\"]/u.test(value)) {\\n+    throw new Error(\\\"Windows codex arguments cannot contain %, quotes, or control characters\\\");\\n+  }\\n+  if (value.length === 0) return '\\\"\\\"';\\n+  if (!/[\\\\s&()^|<>!]/u.test(value)) return value;\\n+  return `\\\"${value}\\\"`;\\n+}\\n+\\n+function spawnCodex(argv, opts) {\\n+  const spawnOptions = { cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"] };\\n+  if (process.platform !== \\\"win32\\\") return spawn(\\\"codex\\\", argv, spawnOptions);\\n+  const commandLine = [\\\"codex\\\", ...argv].map(quoteForCmd).join(\\\" \\\");\\n+  return spawn(\\\"cmd.exe\\\", [\\\"/d\\\", \\\"/v:off\\\", \\\"/s\\\", \\\"/c\\\", commandLine], {\\n+    ...spawnOptions,\\n+    windowsHide: true,\\n+  });\\n+}\\n+\\n function dispatchToCodex(opts, brief, run, writeResult) {\\n   const argv = buildArgv(opts, run.finalPath);\\n-  // shell:true on Windows so the codex.cmd shim resolves (see codexVersion). Safe:\\n-  // the brief is fed via child.stdin below — never argv — and argv holds only\\n-  // sandbox enums, model names, and file paths, with no shell metacharacters.\\n-  const child = spawn(\\\"codex\\\", argv, { cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"], shell: process.platform === \\\"win32\\\" });\\n+  let child;\\n+  try {\\n+    child = spawnCodex(argv, opts);\\n+  } catch (err) {\\n+    const result = writeResult({ status: \\\"failed\\\", exitCode: 1, signal: null, threadId: null, finalMessage: \\\"\\\", touchedFiles: gitTouchedFiles(opts.cd), error: String(err.message || err) });\\n+    printSummary(result, run.resultPath);\\n+    process.exit(1);\\n+  }\\n \\n   let threadId = null;\\n   let stdoutBuf = \\\"\\\";\\ndiff --git a/tests/codex-relay.test.mjs b/tests/codex-relay.test.mjs\\nnew file mode 100644\\nindex 0000000..0bc344e\\n--- /dev/null\\n+++ b/tests/codex-relay.test.mjs\\n@@ -0,0 +1,92 @@\\n+import test from 'node:test';\\n+import assert from 'node:assert/strict';\\n+import { spawnSync } from 'node:child_process';\\n+import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, chmodSync } from 'node:fs';\\n+import { tmpdir } from 'node:os';\\n+import { join, resolve } from 'node:path';\\n+\\n+const relay = resolve('skills/codex-delegate/scripts/relay.mjs');\\n+\\n+// Exercise the Windows command builder independently of the host OS. Native\\n+// .cmd resolution and cmd parsing still require a Windows smoke test.\\n+test('Windows quoting preserves argument boundaries and rejects cmd expansion', async () => {\\n+  const source = readFileSync(relay, 'utf8');\\n+  const start = source.indexOf('function quoteForCmd(');\\n+  const end = source.indexOf('\\\\nfunction spawnCodex(', start);\\n+  assert.ok(start !== -1 && end !== -1);\\n+  const quoteForCmd = new Function(`${source.slice(start, end)}; return quoteForCmd;`)();\\n+  assert.equal(quoteForCmd('C:\\\\\\\\Users\\\\\\\\Mahmoud Sabry\\\\\\\\AppData\\\\\\\\Local\\\\\\\\Temp\\\\\\\\final.txt'), '\\\"C:\\\\\\\\Users\\\\\\\\Mahmoud Sabry\\\\\\\\AppData\\\\\\\\Local\\\\\\\\Temp\\\\\\\\final.txt\\\"');\\n+  assert.equal(quoteForCmd('C:\\\\\\\\Users\\\\\\\\a&b\\\\\\\\final.txt'), '\\\"C:\\\\\\\\Users\\\\\\\\a&b\\\\\\\\final.txt\\\"');\\n+  assert.equal(quoteForCmd(''), '\\\"\\\"');\\n+  assert.equal(quoteForCmd('-'), '-');\\n+  for (const unsafe of ['%PATH%', 'bad\\\" & echo injected', 'line\\\\nnext', 'line\\\\rnext', 'nul\\\\0byte']) {\\n+    assert.throws(() => quoteForCmd(unsafe));\\n+  }\\n+});\\n+\\n+test('POSIX relay forwards stdin and spaced output path and records artifacts', { skip: process.platform === 'win32' }, () => {\\n+  const root = mkdtempSync(join(tmpdir(), 'codex-relay-test-'));\\n+  const bin = join(root, 'bin');\\n+  const out = join(root, 'output with spaces');\\n+  mkdirSync(bin);\\n+  mkdirSync(out);\\n+  const fakeCodex = join(bin, 'codex');\\n+  writeFileSync(fakeCodex, `#!/usr/bin/env node\\n+const fs = require('node:fs');\\n+if (process.argv[2] === '--version') { console.log('codex-test 1'); process.exit(0); }\\n+const args = process.argv.slice(2);\\n+const finalPath = args[args.indexOf('-o') + 1];\\n+let input = '';\\n+process.stdin.on('data', chunk => input += chunk);\\n+process.stdin.on('end', () => {\\n+  fs.writeFileSync(finalPath, input === 'Say PING' ? 'PING_FROM_CODEX\\\\\\\\n' : 'unexpected brief');\\n+  console.log(JSON.stringify({type:'thread.started',thread_id:'test-thread'}));\\n+});\\n+`);\\n+  chmodSync(fakeCodex, 0o755);\\n+  const brief = join(root, 'brief.txt');\\n+  writeFileSync(brief, 'Say PING');\\n+  const run = spawnSync(process.execPath, [relay, '--brief', brief, '--cd', root, '--read-only', '--skip-git-repo-check', '--out-dir', out], {\\n+    encoding: 'utf8', env: { ...process.env, PATH: `${bin}:${process.env.PATH}` },\\n+  });\\n+  assert.equal(run.status, 0, run.stderr);\\n+  const result = JSON.parse(readFileSync(join(out, 'result.json'), 'utf8'));\\n+  assert.equal(result.status, 'completed');\\n+  assert.equal(result.exitCode, 0);\\n+  assert.equal(result.finalMessage, 'PING_FROM_CODEX');\\n+  assert.equal(result.threadId, 'test-thread');\\n+  assert.equal(result.sandbox, 'read-only');\\n+  assert.equal(result.touchedFiles, null);\\n+  assert.equal(readFileSync(join(out, 'final.txt'), 'utf8').trim(), 'PING_FROM_CODEX');\\n+  assert.equal(readFileSync(join(out, 'brief.txt'), 'utf8'), 'Say PING');\\n+  assert.match(readFileSync(join(out, 'events.jsonl'), 'utf8'), /thread.started/);\\n+});\\n+\\n+test('default temp output directory may contain spaces', { skip: process.platform === 'win32' }, () => {\\n+  const root = mkdtempSync(join(tmpdir(), 'default-relay-test-'));\\n+  const bin = join(root, 'bin');\\n+  const tempRoot = join(root, 'temp with spaces');\\n+  mkdirSync(bin);\\n+  mkdirSync(tempRoot);\\n+  const fake = join(bin, 'codex');\\n+  writeFileSync(fake, `#!/usr/bin/env node\\n+const fs = require('node:fs');\\n+if (process.argv[2] === '--version') { console.log('test-version'); process.exit(0); }\\n+const args = process.argv.slice(2);\\n+const dest = args[args.indexOf('-o') + 1];\\n+process.stdin.resume();\\n+process.stdin.on('end', () => fs.writeFileSync(dest, 'PING_FROM_CODEX'));\\n+`);\\n+  chmodSync(fake, 0o755);\\n+  const run = spawnSync(process.execPath, [relay, '--cd', root, '--read-only', '--skip-git-repo-check'], {\\n+    encoding: 'utf8', input: 'Say PING',\\n+    env: { ...process.env, TMPDIR: tempRoot, PATH: `${bin}:${process.env.PATH}` },\\n+  });\\n+  assert.equal(run.status, 0, run.stderr);\\n+  const match = run.stdout.match(/^result: (.+result\\\\.json)$/m);\\n+  assert.ok(match, run.stdout);\\n+  assert.ok(match[1].includes('temp with spaces'));\\n+  const result = JSON.parse(readFileSync(match[1], 'utf8'));\\n+  assert.equal(result.status, 'completed');\\n+  assert.equal(result.finalMessage, 'PING_FROM_CODEX');\\n+});\\n\"").encode('utf-8')
